internal static readonly @string sha256ˢ = "sha256"u8;

public static void TestGolden(ж<testing.T> Ꮡt) {
    cryptotest.TestAllImplementations(Ꮡt, sha256ˢ, testGolden);
}

internal static void testGolden(ж<testing.T> Ꮡt) {
    foreach (var (_, g) in golden) {
        @string s = fmt.Sprintf("%x"u8, Sum256(slice<byte>(g.@in)));
        if (s != g.@out) {
            Ꮡt.Fatalf("Sum256 function: sha256(%s) = %s want %s"u8, g.@in, s, g.@out);
        }
        var c = New();
        for (nint j = 0; j < 3; j++) {
            if (j < 2){
                io.WriteString(c, g.@in);
            } else {
                io.WriteString(c, g.@in.slice(0, len(g.@in) / 2));
                c.Sum(default!);
                io.WriteString(c, g.@in.slice(len(g.@in) / 2));
            }
            @string sΔ1 = fmt.Sprintf("%x"u8, c.Sum(default!));
            if (sΔ1 != g.@out) {
                Ꮡt.Fatalf("sha256[%d](%s) = %s want %s"u8, j, g.@in, sΔ1, g.@out);
            }
            c.Reset();
        }
    }
    foreach (var (_, g) in golden224) {
        @string s = fmt.Sprintf("%x"u8, Sum224(slice<byte>(g.@in)));
        if (s != g.@out) {
            Ꮡt.Fatalf("Sum224 function: sha224(%s) = %s want %s"u8, g.@in, s, g.@out);
        }
        var c = New224();
        for (nint j = 0; j < 3; j++) {
            if (j < 2){
                io.WriteString(c, g.@in);
            } else {
                io.WriteString(c, g.@in.slice(0, len(g.@in) / 2));
                c.Sum(default!);
                io.WriteString(c, g.@in.slice(len(g.@in) / 2));
            }
            @string sΔ1 = fmt.Sprintf("%x"u8, c.Sum(default!));
            if (sΔ1 != g.@out) {
                Ꮡt.Fatalf("sha224[%d](%s) = %s want %s"u8, j, g.@in, sΔ1, g.@out);
            }
            c.Reset();
        }
    }
}

public static void TestGoldenMarshal(ж<testing.T> Ꮡt) {
    cryptotest.TestAllImplementations(Ꮡt, sha256ˢ, testGoldenMarshal);
}

internal partial struct testGoldenMarshal_tests /*dyn*/ {
    internal @string name;
    internal Func<hash.Hash> newHash;
    internal slice<sha256Test> gold;
}

internal static void testGoldenMarshal(ж<testing.T> Ꮡt) {
    var tests = new testGoldenMarshal_tests[]{
        new("256"u8, New, golden),
        new("224"u8, New224, golden224)
    }.slice();
    foreach (var (_, vᴛ1) in tests) {
        ref var tt = ref heap(new testGoldenMarshal_tests(), out var Ꮡtt);
        tt = vᴛ1;

        var ttʗ1 = tt;
        Ꮡt.Run(tt.name, (ж<testing.T> tΔ1) => {
            foreach (var (_, g) in ttʗ1.gold) {
                var h = ttʗ1.newHash();
                var h2 = ttʗ1.newHash();
                io.WriteString(h, g.@in.slice(0, len(g.@in) / 2));
                var (state, err) = h._<encoding.BinaryMarshaler>().MarshalBinary();
                if (err != default!) {
                    tΔ1.Errorf("could not marshal: %v"u8, err);
                    continue;
                }
                (var stateAppend, err) = h._<encoding.BinaryAppender>().AppendBinary(new slice<byte>(4, 32));
                if (err != default!) {
                    tΔ1.Errorf("could not marshal: %v"u8, err);
                    continue;
                }
                stateAppend = stateAppend[4..];
                if (((sstring)state) != g.halfState) {
                    tΔ1.Errorf("sha%s(%q) state = %q, want %q"u8, ttʗ1.name, g.@in, state, g.halfState);
                    continue;
                }
                if (((sstring)stateAppend) != g.halfState) {
                    tΔ1.Errorf("sha%s(%q) stateAppend = %q, want %q"u8, ttʗ1.name, g.@in, stateAppend, g.halfState);
                    continue;
                }
                {
                    var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state); if (errΔ1 != default!) {
                        tΔ1.Errorf("could not unmarshal: %v"u8, errΔ1);
                        continue;
                    }
                }
                io.WriteString(h, g.@in.slice(len(g.@in) / 2));
                io.WriteString(h2, g.@in.slice(len(g.@in) / 2));
                {
                    var (actual, actual2) = (h.Sum(default!), h2.Sum(default!)); if (!bytes.Equal(actual, actual2)) {
                        tΔ1.Errorf("sha%s(%q) = 0x%x != marshaled 0x%x"u8, ttʗ1.name, g.@in, actual, actual2);
                    }
                }
            }
        });
    }
}

public static void TestMarshalTypeMismatch(ж<testing.T> Ꮡt) {
    var h1 = New();
    var h2 = New224();
    var (state1, err) = h1._<encoding.BinaryMarshaler>().MarshalBinary();
    if (err != default!) {
        Ꮡt.Errorf("could not marshal: %v"u8, err);
    }
    {
        var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state1); if (errΔ1 == default!) {
